#Requires -Version 5.1
# feat-planificador-permisos-highlight-hoy.ps1
#
# CAUSA DEL PROBLEMA DE PERMISOS:
# 1. FRONTEND: No existia guard "puedeReordenar" — cualquier usuario podia
#    disparar el reorder en el cliente, pero Supabase lo rechazaba.
# 2. RLS: obras_update tiene USING (get_user_role() = 'admin') en la migracion
#    001_initial_schema.sql. Pilar (rol Oficina, no admin) recibe error al
#    intentar guardar el nuevo orden_gantt. Ver SQL de migracion al final.
#
# CAMBIOS EN FRONTEND (planificacion/page.tsx):
# 1. puedeReordenar = isAdmin || canDo("planificacion","editar")
#    Guard en handleDragEnd antes del arrayMove + Promise.all update
#    Grip handle: cursor-default + opacity-30 si no puede reordenar
# 2. activeOver: estado { obraId, dateStr } actualizado en onDragOver
#    Highlight: celda exacta = bg-blue-100 + ring-2 ring-blue-400
#              fila de la obra = bg-blue-50
#              columna del dia = bg-blue-50/60
#    Se limpia en onDragEnd y onDragCancel
# 3. Dia actual: bg-brand-100 + border-b-2 border-b-brand-500 + label "hoy"
#    antes era bg-brand-50 (muy sutil); ahora es claramente visible
#
# MIGRACION RLS NECESARIA (ejecutar en Supabase SQL Editor):
# DROP POLICY IF EXISTS "obras_update" ON obras;
# CREATE POLICY "obras_update" ON obras FOR UPDATE USING (
#   get_user_role() = 'admin'
#   OR EXISTS (
#     SELECT 1 FROM users u
#     JOIN rol_permisos rp ON rp.rol_id = u.rol_id
#     WHERE u.id = auth.uid()
#       AND rp.pantalla IN ('obras', 'planificacion')
#       AND rp.editar = true
#   )
# );

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> feat: planificador permisos + highlight + hoy" -ForegroundColor Cyan

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\planificacion\page.tsx"), $bytes)

$c = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\planificacion\page.tsx"), [System.Text.Encoding]::UTF8)
if ($c.Contains("puedeReordenar"))       { Write-Host "  OK: puedeReordenar definido" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($c.Contains("if (!puedeReordenar)")) { Write-Host "  OK: guard en handleDragEnd" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($c.Contains("bg-blue-100 ring-2"))   { Write-Host "  OK: highlight celda drag" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($c.Contains("bg-brand-100 font-bold")) { Write-Host "  OK: dia actual destacado" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($c.Contains("onDragOver"))           { Write-Host "  OK: onDragOver tracking" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }

Write-Host ""
Write-Host "  IMPORTANTE: Ejecutar en Supabase SQL Editor la migracion RLS" -ForegroundColor Yellow
Write-Host "  (ver comentarios al inicio del script)"
Write-Host ""
Write-Host "  git add src\app\planificacion\page.tsx"
Write-Host '  git commit -m "feat: planificador reordenar por permiso + highlight drag + dia actual"'
Write-Host "  git push"
